                                        gnutls_assert();
                                        goto done;
                                }

                                ret =
                                    gnutls_x509_crt_import(this_cert,
                                                           &data,
                                                           GNUTLS_X509_FMT_DER);
                                if (ret < 0) {
                                        gnutls_assert();
                                        gnutls_x509_crt_deinit(this_cert);
                                        this_cert = NULL;
                                        goto done;
                                }

                                /* check if the key id match */
                                cert_id_size = sizeof(cert_id);
                                ret =
                                    gnutls_x509_crt_get_key_id(this_cert,
                                                               0, cert_id,
                                                               &cert_id_size);
                                if (ret < 0) {
                                        gnutls_assert();
                                        gnutls_x509_crt_deinit(this_cert);
                                        this_cert = NULL;
                                        goto done;
                                }

